138	// Stream the message file into HMAC-SHA-256 a fixed-size chunk at a time.
139	// The message is never stored whole: regardless of file length, only one
140	// 64 KiB read buffer is needed on top of the constant-size HMAC context.
141	//
142	// The bytes are not interpreted as text: the file is opened in binary mode,
143	// trailing newlines are kept, line endings are not converted and zero bytes
144	// are preserved. An empty file simply yields no Update calls, which
145	// authenticates the empty message.
146	enum class HmacStatus { kSuccess, kReadError, kCryptoError };
147	
148	HmacStatus hmacSha256File(const std::vector<unsigned char>& key,
149	                          const std::string& path,
150	                          std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
151	                          std::size_t& macLength) {
152	    HMAC_CTX* rawCtx = HMAC_CTX_new();
153	    if (rawCtx == nullptr) {
154	        return HmacStatus::kCryptoError;
155	    }
156	    std::unique_ptr<HMAC_CTX, decltype(&HMAC_CTX_free)> ctx(rawCtx,
157	                                                            HMAC_CTX_free);
158	
159	    // Init with the key and SHA-256. HMAC_Init_ex performs the standard
160	    // RFC 2104 key normalization itself, so keys longer than the SHA-256
161	    // block size are hashed exactly as the standard requires; the resulting
162	    // tag is identical to the one-shot HMAC() interface on both OpenSSL
163	    // 1.1.1 and OpenSSL 3.x. The key is validated to be non-empty before
164	    // this is called, so key.data() is always valid.
165	    if (HMAC_Init_ex(ctx.get(), key.data(), static_cast<int>(key.size()),
166	                     EVP_sha256(), nullptr) != 1) {
167	        return HmacStatus::kCryptoError;
168	    }
169	
170	    std::ifstream in(path, std::ios::binary | std::ios::in);
171	    if (!in) {
172	        return HmacStatus::kReadError;
173	    }
174	
175	    std::array<char, 65536> buffer{};
176	    while (in.read(buffer.data(), static_cast<std::streamsize>(buffer.size()))) {
177	        if (HMAC_Update(ctx.get(),
178	                        reinterpret_cast<const unsigned char*>(buffer.data()),
179	                        static_cast<std::size_t>(in.gcount())) != 1) {
180	            return HmacStatus::kCryptoError;
181	        }
182	    }
183	    // A read error (including one that happens after part of the message has
184	    // already been fed to HMAC) aborts authentication: Final is never called,
185	    // so no partial-message tag can be produced. EOF with a short final read
186	    // is normal and those remaining bytes must still participate.
187	    if (in.bad()) {
188	        return HmacStatus::kReadError;
189	    }
190	    if (in.gcount() > 0) {
191	        if (HMAC_Update(ctx.get(),
192	                        reinterpret_cast<const unsigned char*>(buffer.data()),
193	                        static_cast<std::size_t>(in.gcount())) != 1) {
194	            return HmacStatus::kCryptoError;
195	        }
196	    }
197	
198	    unsigned int outLength = 0;
199	    if (HMAC_Final(ctx.get(), mac.data(), &outLength) != 1) {
200	        return HmacStatus::kCryptoError;
201	    }
202	    macLength = outLength;
203	    return HmacStatus::kSuccess;
204	}
