223	        return 2;
224	    }
225	
226	    std::array<unsigned char, EVP_MAX_MD_SIZE> mac{};
227	    std::size_t macLength = 0;
228	    switch (hmacSha256File(key, filePath, mac, macLength)) {
229	        case HmacStatus::kReadError:
230	            std::cerr << "messagetag tag: error: failed to read file: "
231	                      << filePath << "\n";
232	            return 1;
233	        case HmacStatus::kCryptoError:
234	            std::cerr << "messagetag tag: error: HMAC-SHA-256 computation failed\n";
